  const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const busyRef = useRef(false); const [error, setError] = useState(""); const [slots, setSlots] = useState<Array<{ startsAt?: string; scheduledAt?: string }>>([]); const [availabilityBusy, setAvailabilityBusy] = useState(false);
  const attempt = useRef({ fingerprint: "", key: crypto.randomUUID() });
