  const patientField = <Field name="patientId" label={t("workflow.text.patient")} values={values} set={set} required><option value="">{t("workflow.text.chooseAPatient")}</option>{snapshot.patients.map(p => <option value={p.id} key={p.id}>{patientName(p)}</option>)}</Field>;
