  const titles: Record<Modal["kind"], string> = { patient: m.patient ? t("workflow.text.aLittleUpdate") : t("workflow.text.aNewFaceAWarmWelcome"), booking: m.appointment ? t("workflow.text.updateThisAppointment") : t("workflow.text.makeRoomForGoodCare"), upload: m.document ? t("workflow.text.aFreshVersion") : t("workflow.text.addADocument"), review: t("workflow.text.giveThisVersionALook"), archive: t("workflow.text.archiveThisDocument"), restore: t("workflow.text.restoreThisDocument"), cancel: t("workflow.text.cancelThisAppointment"), request: t("workflow.text.aLittleHelpGettingReady"), template: m.template ? t("workflow.text.aNewDraft") : t("workflow.text.createAFamiliarWelcome"), prepare: t("workflow.text.prepareAPatientDocument"), waiver: t("workflow.text.waiveThisRequirement"), revoke: t("workflow.text.revokeThisWaiver"), "request-cancel": t("workflow.text.cancelThisRequest"), reconcile: t("workflow.text.updateThisVisitSChecklist"), evidence: t("workflow.text.useAnExistingDocumentMessage") };
  const descriptions: Partial<Record<Modal["kind"], string>> = { upload: t("workflow.text.pdfJPEGOrPNGUpTo10MBFilesAreCheckedBeforeStaffCanReviewThem"), review: t("workflow.text.yourDecisionAppliesToThisExactVersionRejectedDocumentsDoNotSatisfyReadiness"), archive: t("workflow.text.theFileAndItsHistoryStayPreservedRequirementsMayNeedNewEvidence"), restore: t("workflow.text.restoringKeepsAllEarlierVersionsAndReviewHistory"), cancel: t("workflow.text.thisRecordsTheCancellationAndUpdatesRelatedWork"), template: t("workflow.text.publishedVersionsStayIntactAddTheFieldsPatientsOrStaffWillComplete"), prepare: t("workflow.text.theServerWillRenderADocumentFromThePublishedTemplateAndTheseAnswers"), request: t("workflow.text.createASecurePatientRequestThenConfirmDeliveryStatusInThePatientProfile"), reconcile: t("workflow.text.currentPublishedRulesReplaceThisVisitSSnapshotExistingEvidenceIsRecheckedRequirementsMayBecomeIncomplete"), evidence: t("workflow.text.theServerChecksTheDocumentSPatientTypeReviewSignatureAgeAndReusePolicyBeforeAttachingIt"), waiver: t("workflow.text.includeAReasonAWaiverChangesReadinessAndLeavesAPermanentActivityRecord"), revoke: t("workflow.text.includeAReasonThisRequirementWillNeedEvidenceAgain") };
