  async function availability() { setAvailabilityBusy(true); setError(""); try { const result = await adapter.detail<{ slots: Array<{ startsAt?: string; scheduledAt?: string }> }>(`availability?providerId=${encodeURIComponent(values.providerId)}&date=${values.scheduledAt.slice(0, 10)}&durationMinutes=${values.durationMinutes}`); setSlots(result.slots ?? []); } catch (cause) { setError(cause instanceof WorkflowInputError ? cause.message : uiError(cause, "workflow.text.availabilityCouldNotBeLoaded")); } finally { setAvailabilityBusy(false); } }
